<?php session_start();if(isset($_SESSION['user_id'])){header('Location: dashboard.php');exit;}require_once 'includes/header.php'; ?>
<section class="auth-page"><div class="auth-image register-image"><div><span class="eyebrow">JOIN VS TRAVELLS</span><h1>Your next drive is closer than you think.</h1><p>Create your customer profile and start requesting vehicles.</p></div></div><div class="auth-panel"><form id="regForm" class="auth-form"><span class="eyebrow dark">CREATE ACCOUNT</span><h2>Start your journey</h2><div id="msg"></div><label>Full name<input id="name" required placeholder="Your full name"></label><label>Email address<input type="email" id="email" required placeholder="you@example.com"></label><label>Password<input type="password" id="password" minlength="6" required placeholder="Minimum 6 characters"></label><button class="btn wide">Create account</button><p class="auth-switch">Already registered? <a href="login.php">Sign in</a></p></form></div></section>
<script>regForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('api/auth/register.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,email:email.value,password:password.value})}),j=await r.json();msg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`;if(j.success)setTimeout(()=>location.href='login.php',800)}</script>
